import{_ as a,o as e,c as l,a2 as s}from"./chunks/framework.Dxeykp0S.js";const u=JSON.parse('{"title":"毕业设计 · 多用户任务协作平台：从 0 到 1 上线","description":"","frontmatter":{},"headers":[],"relativePath":"pro/07-final-project.md","filePath":"pro/07-final-project.md","lastUpdated":1787141678000}'),o={name:"pro/07-final-project.md"};function n(i,t,r,p,d,c){return e(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="毕业设计-·-多用户任务协作平台-从-0-到-1-上线" tabindex="-1">毕业设计 · 多用户任务协作平台：从 0 到 1 上线 <a class="header-anchor" href="#毕业设计-·-多用户任务协作平台-从-0-到-1-上线" aria-label="Permalink to &quot;毕业设计 · 多用户任务协作平台：从 0 到 1 上线&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>终极任务，没有阅读材料、没有步骤分解——只有需求、验收标准，和你在这 24 个任务里积累的一切。把它当作一个真实的商业项目来对待。</p><h2 id="项目背景" tabindex="-1">项目背景 <a class="header-anchor" href="#项目背景" aria-label="Permalink to &quot;项目背景&quot;">​</a></h2><p>构建并上线一个<strong>多用户任务协作平台</strong>（可以理解为迷你版 Linear/Trello 的后端）：团队管理任务、实时协作、异步通知。功能本身不新鲜——新鲜感在于你要用全新的技术栈，以生产级标准独立完成全链路。</p><h2 id="功能需求" tabindex="-1">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h2><p><strong>核心领域</strong></p><ol><li>用户体系：注册、OAuth2 + JWT 登录（access + refresh token 轮换）</li><li>团队与权限：用户可创建团队、邀请成员；角色分 owner/member，接口级权限控制（scopes）</li><li>任务管理：任务属于团队和项目，支持指派、状态流转（todo/doing/done）、优先级、截止时间</li><li>评论与动态：任务下可评论；关键操作（创建/指派/完成）产生动态流</li></ol><p><strong>实时与异步</strong></p><ol start="5"><li>WebSocket 实时推送：任务状态变更、新评论实时推送给在线的团队成员（FastAPI 原生支持 WebSocket，配合 Redis pub/sub 做跨实例广播）</li><li>异步通知：任务被指派/临期时，通过 Celery 队列异步发送通知（邮件可 mock，写入通知表即可），支持失败重试</li></ol><p><strong>数据与缓存</strong></p><ol start="7"><li>PostgreSQL 持久化：SQLAlchemy 2.0 + Alembic 迁移，关系建模（用户/团队/项目/任务/评论/通知）</li><li>Redis 缓存：任务列表、动态流的 cache-aside 缓存与正确的失效策略</li></ol><p><strong>工程质量</strong></p><ol start="9"><li>完整类型标注，mypy strict 通过；ruff 零告警</li><li>pytest 覆盖率 ≥ 70%：认证、权限、任务流转、缓存失效必须有测试</li><li>pydantic-settings 配置 + structlog 结构化日志（带 request_id）+ /metrics 指标端点</li></ol><p><strong>部署运维</strong></p><ol start="12"><li>生产级 Dockerfile（多阶段、非 root、锁定依赖）</li><li>compose.yaml 一键起全套：app + worker + Postgres + Redis</li><li>K8s 清单：app 与 worker 分离的 Deployment + Service + HPA + 探针 + 资源限额</li><li>CI：pre-commit + GitHub Actions（lint / typecheck / test / build image）</li></ol><h2 id="架构提示-不强制" tabindex="-1">架构提示（不强制） <a class="header-anchor" href="#架构提示-不强制" aria-label="Permalink to &quot;架构提示（不强制）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┐   HTTP/WS   ┌─────────────┐   SQL    ┌────────────┐</span></span>
<span class="line"><span>│  Client  │ ◄────────► │ FastAPI app  │ ──────► │ PostgreSQL │</span></span>
<span class="line"><span>└─────────┘             │  (n replicas)│          └────────────┘</span></span>
<span class="line"><span>                        │              │   ┌────► │   Redis    │</span></span>
<span class="line"><span>                        └──────┬───────┘   │      │ cache+queue│</span></span>
<span class="line"><span>                               │ enqueue    │      └─────┬──────┘</span></span>
<span class="line"><span>                        ┌──────▼───────┐   │            │ pop job</span></span>
<span class="line"><span>                        │ celery worker │ ◄─┴────────────┘</span></span>
<span class="line"><span>                        └──────────────┘</span></span></code></pre></div><p>WebSocket 跨实例广播是本项目最难的点：多副本下，A 实例上的操作要推给连在 B 实例上的用户——Redis pub/sub 是标准解法。</p><h2 id="验收清单" tabindex="-1">验收清单 <a class="header-anchor" href="#验收清单" aria-label="Permalink to &quot;验收清单&quot;">​</a></h2><ul><li>[ ] 本地 <code>docker compose up</code> 一键运行，README 有清晰说明</li><li>[ ] 两个浏览器会话（不同用户）能通过 WebSocket 实时看到对方的任务变更</li><li>[ ] 异步通知可观测：提交任务后能追踪 job 状态</li><li>[ ] <code>kubectl apply</code> 到本地 kind 集群后服务可用，滚动更新不中断请求</li><li>[ ] CI 全绿</li><li>[ ] 一篇项目复盘笔记：架构决策、踩坑记录、如果重来会怎么做</li></ul><h2 id="评分维度-自评" tabindex="-1">评分维度（自评） <a class="header-anchor" href="#评分维度-自评" aria-label="Permalink to &quot;评分维度（自评）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>权重</th><th>说明</th></tr></thead><tbody><tr><td>功能完整性</td><td>30%</td><td>需求 1-8 全部可用</td></tr><tr><td>Python 代码质量</td><td>25%</td><td>类型、测试、lint、是否 Pythonic</td></tr><tr><td>实时与异步</td><td>20%</td><td>WebSocket 广播正确性、队列可靠性</td></tr><tr><td>运维成熟度</td><td>25%</td><td>容器化、K8s、可观测性</td></tr></tbody></table><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>从预备班敲下第一行 <code>uv init</code>，到今天独立上线一个生产级的 Python 后端服务——你已经完成了从 &quot;Python 零基础&quot; 到 &quot;Python 后端工程师&quot; 的转变。</p><p>但请记住学园介绍里的那句话：<strong>这里只是个辅助，一切的成长和进步一定依赖于你自己，也归功于你自己。</strong></p><p>恭喜你，毕业了。</p><h2 id="毕业后去哪里" tabindex="-1">毕业后去哪里 <a class="header-anchor" href="#毕业后去哪里" aria-label="Permalink to &quot;毕业后去哪里&quot;">​</a></h2><ul><li>把学习笔记和毕业设计复盘整理成博客，分享从 Python 入门到后端项目上线的完整过程</li><li>参与 Python 开源生态：给 FastAPI、SQLAlchemy、pydantic、uv、Celery 提 issue 或 PR</li><li>继续深挖：PostgreSQL 进阶（索引、查询计划）、分布式系统（消息队列 at-least-once、分布式锁）</li><li>持续输入：<a href="https://realpython.com/" target="_blank" rel="noreferrer">Real Python</a>、<a href="https://blog.python.org/" target="_blank" rel="noreferrer">Python 官方博客</a>、PyCon 演讲</li></ul>`,29)])])}const b=a(o,[["render",n]]);export{u as __pageData,b as default};
